BEGIN;
insert into public.ta_lessons(course_slug,lesson_no,title_pl,material) values
('gontarz',0,'1. Drewniany dach od podstaw: gont, spån i warstwy','{"module":1,"curriculum_revision":4,"lesson_kind":"technical_curriculum","editorial_status":"review_needed","sections":[{"heading":"Czym zajmuje się gontarz","text":"Gontarz przygotowuje elementy drewnianego pokrycia i rozumie, jak łączą się one w szczelny układ odprowadzający wodę. Nie należy mylić gontu drewnianego z bitumicznym gontem dachowym. W tradycji spotyka się różne odmiany: łupane, cięte i strugane, różniące się powierzchnią, grubością, geometrią i sposobem nakładania."},{"heading":"Poznaj element i warstwy","text":"Pojedynczy gont ma grubszy koniec dolny (butt), cieńszy górny oraz powierzchnię zewnętrzną. Widoczna część gontu to ekspozycja (weather exposure), a reszta zostaje zakryta przez sąsiednie rzędy. Warstwy i zakłady przenoszą deszczówkę w dół, w kierunku okapu. Szczelność nie wynika z tego, że każdy styk boczny jest szczelnym klejonym połączeniem."},{"heading":"Uwaga na języki i regionalne techniki","text":"W Norwegii określenia takspon, takflis, stikker i takshingel mają regionalną historię. Nie odnoszą się zawsze do identycznego detalu. Lokalny gont może być układany na zakład boczny, podczas gdy nowoczesny cięty cedar shingle bywa montowany z kontrolowaną szczeliną i przesunięciem styków. Ucz się rozpoznawać typ z rysunku, nie wyłącznie po nazwie."},{"heading":"Przykład projektu","text":"Dwa dachy mają ten sam kąt nachylenia, lecz inny materiał: historyczne takspon na kościele i współczesne cięte cedar shingles na nowym domu. Ich mocowania i zakłady mogą być odmienne. Błędem byłoby skopiowanie jednego detalu na drugi bez informacji o konkretnym wyrobie."},{"heading":"Ćwiczenie na rysunku","text":"Narysuj trzy kolejne rzędy gontów i strzałkami pokaż spływ wody. Podpisz okap, kalenicę, łatę, ekspozycję, zakład, łączenie gontów oraz podłoże. Dopisz, które elementy wymagają dokumentacji producenta lub projektu konstrukcyjnego."}],"illustration":"gontarz-warstwy","references":[{"label":"Źródło techniczne","url":"https://snl.no/takspon"}],"learning":{"intro":"Gontarz przygotowuje elementy drewnianego pokrycia i rozumie, jak łączą się one w szczelny układ odprowadzający wodę. Nie należy mylić gontu drewnianego z bitumicznym gontem dachowym. W tradycji spotyka się różne odmiany: łupane, cięte i strugane, różniące się powierzchnią, grubością, geometrią i sposobem nakładania.","situation":"Dwa dachy mają ten sam kąt nachylenia, lecz inny materiał: historyczne takspon na kościele i współczesne cięte cedar shingles na nowym domu. Ich mocowania i zakłady mogą być odmienne. Błędem byłoby skopiowanie jednego detalu na drugi bez informacji o konkretnym wyrobie.","task":"Narysuj trzy kolejne rzędy gontów i strzałkami pokaż spływ wody. Podpisz okap, kalenicę, łatę, ekspozycję, zakład, łączenie gontów oraz podłoże. Dopisz, które elementy wymagają dokumentacji producenta lub projektu konstrukcyjnego.","question":"Dlaczego gont drewniany nie musi mieć szczelnie sklejonych wszystkich styków bocznych?","options":["Ponieważ prawidłowe warstwy i zakłady kierują wodę ku okapowi.","Ponieważ drewno nigdy nie chłonie wody.","Ponieważ szczelność dachu zapewnia wyłącznie lakier.","Ponieważ zakład nie ma znaczenia, jeśli użyto gwoździ."],"correct":0,"example":"Ponieważ prawidłowe warstwy i zakłady kierują wodę ku okapowi.","explanation":"Pracuje cały układ pokrycia: spadek, zakłady, układ styków i detale odprowadzania wody.","feedback":["Prawidłowo. Pracuje cały układ pokrycia: spadek, zakłady, układ styków i detale odprowadzania wody.","Wróć do zależności opisanej w zadaniu. Pracuje cały układ pokrycia: spadek, zakłady, układ styków i detale odprowadzania wody.","Wróć do zależności opisanej w zadaniu. Pracuje cały układ pokrycia: spadek, zakłady, układ styków i detale odprowadzania wody.","Wróć do zależności opisanej w zadaniu. Pracuje cały układ pokrycia: spadek, zakłady, układ styków i detale odprowadzania wody."]}}'::jsonb),
('gontarz',1,'2. Materiałoznawstwo gontu: włókna, sęki i wilgoć','{"module":1,"curriculum_revision":4,"lesson_kind":"technical_curriculum","editorial_status":"review_needed","sections":[{"heading":"Dlaczego orientacja włókien ma znaczenie","text":"Drewno wchłania wodę i zmienia wymiary zależnie od wilgotności oraz kierunku anatomicznego. Najtrwalsze elementy pokrycia są zwykle dobierane pod kątem prostolinijnego przebiegu włókien, ograniczenia sęków, pęknięć i młodocianego drewna. Każda wada w obszarze narażonym na wodę może zwiększyć ryzyko odkształcenia lub przyspieszonej degradacji."},{"heading":"Nie zawsze jeden gatunek","text":"W tradycyjnej Skandynawii występowały m.in. gonty z sosny, świerka, osiki i dębu, zależnie od regionu. W produkcji północnoamerykańskiej często używany jest czerwony cedr. Nie porównuj ich wyłącznie kolorem: istotne są struktura drewna, jakość partii, warunki klimatyczne, sposób wykonania i realna karta wyrobu."},{"heading":"Łupanie kontra przecinanie włókien","text":"Łupanie wzdłuż naturalnych włókien może ograniczać odsłonięte przecięte włókna, przez które woda łatwiej wnika. Badania wskazują jednak, że wysoka jakość surowca i poprawny przebieg włókien mogą pozwolić także ciętemu drewnu osiągnąć dobrą trwałość. Hasło ''łupane zawsze lepsze'' jest zbyt uproszczone."},{"heading":"Przykład selekcji partii","text":"Masz trzy próbki: A bez sęków i z prostym przebiegiem włókien; B z dużym sękiem blisko cienkiej krawędzi; C z pęknięciem biegnącym wzdłuż i przez grubość. A jest lepszym kandydatem do dalszej oceny, a B i C wymagają odrzucenia lub kwalifikacji zgodnie z wymaganiami wyrobu. Sama obecność ładnej powierzchni nie wystarcza."},{"heading":"Karta oceny drewna","text":"Dla sześciu próbek przygotuj tabelę: gatunek, metoda wytwarzania, przebieg włókien, sęki, pęknięcia, orientacja słojów, wilgotność, przeznaczenie, decyzja. Wpisz, których parametrów nie da się wiarygodnie ocenić jedynie wzrokiem."}],"illustration":"gontarz-wlokna","references":[{"label":"Źródło techniczne","url":"https://www.sciencedirect.com/org/science/article/pii/S2772318622000029"}],"learning":{"intro":"Drewno wchłania wodę i zmienia wymiary zależnie od wilgotności oraz kierunku anatomicznego. Najtrwalsze elementy pokrycia są zwykle dobierane pod kątem prostolinijnego przebiegu włókien, ograniczenia sęków, pęknięć i młodocianego drewna. Każda wada w obszarze narażonym na wodę może zwiększyć ryzyko odkształcenia lub przyspieszonej degradacji.","situation":"Masz trzy próbki: A bez sęków i z prostym przebiegiem włókien; B z dużym sękiem blisko cienkiej krawędzi; C z pęknięciem biegnącym wzdłuż i przez grubość. A jest lepszym kandydatem do dalszej oceny, a B i C wymagają odrzucenia lub kwalifikacji zgodnie z wymaganiami wyrobu. Sama obecność ładnej powierzchni nie wystarcza.","task":"Dla sześciu próbek przygotuj tabelę: gatunek, metoda wytwarzania, przebieg włókien, sęki, pęknięcia, orientacja słojów, wilgotność, przeznaczenie, decyzja. Wpisz, których parametrów nie da się wiarygodnie ocenić jedynie wzrokiem.","question":"Która informacja najsilniej wspiera trwałość elementu gontu?","options":["Jednakowy ciemny kolor każdego elementu.","Prosty przebieg włókien i mało wad w wymaganej klasie materiału.","Jak najwięcej dużych sęków blisko cienkiej krawędzi.","Zdolność lakieru do ukrycia pęknięcia przez grubość."],"correct":1,"example":"Prosty przebieg włókien i mało wad w wymaganej klasie materiału.","explanation":"Dobór drewna uwzględnia anatomię i wady; kolor nie stanowi klasy jakości.","feedback":["Wróć do zależności opisanej w zadaniu. Dobór drewna uwzględnia anatomię i wady; kolor nie stanowi klasy jakości.","Prawidłowo. Dobór drewna uwzględnia anatomię i wady; kolor nie stanowi klasy jakości.","Wróć do zależności opisanej w zadaniu. Dobór drewna uwzględnia anatomię i wady; kolor nie stanowi klasy jakości.","Wróć do zależności opisanej w zadaniu. Dobór drewna uwzględnia anatomię i wady; kolor nie stanowi klasy jakości."]}}'::jsonb),
('gontarz',2,'3. Warsztat gontarza: łupanie, ostrza i kontrola geometrii','{"module":1,"curriculum_revision":4,"lesson_kind":"technical_curriculum","editorial_status":"review_needed","sections":[{"heading":"Poznaj trzy rodzaje wykonania","text":"Gont łupany rozdziela drewno wzdłuż jego naturalnych płaszczyzn. Gont cięty powstaje przy użyciu piły, a niektóre regionalne odmiany wykonuje się także przy użyciu strugów. Każdy proces pozostawia inne ślady na powierzchni i może wymagać innych kryteriów kontroli. Celem nie jest nauczenie się niebezpiecznego łupania wyłącznie z tekstu."},{"heading":"Narzędzia mają określone funkcje","text":"Topór i klin służą do kontrolowanego dzielenia surowca w odpowiednim warsztacie. Nóż o szerokim ostrzu typu froe (rozszczepiak) może być używany do rozłupywania i korygowania elementów. Strug pomaga dopracować powierzchnię i grubość, a szablon, miara i kątownik sprawdzają kształt. Narzędzia pomiarowe nie zastępują mechanicznego zabezpieczenia obrabianej części."},{"heading":"Co mierzy gontarz","text":"W dokumentacji elementu określa się długość, szerokość, grubość przy końcu grubszym i cienkim oraz zgodność z projektem. Istotne są także pęknięcia, kierunek włókien i powtarzalność w partii. Trzeba unikać pomiaru pojedynczej deszczułki i zakładania, że cała partia jest taka sama."},{"heading":"Przykład wady cięcia","text":"W partii ciętych gontów o umownej długości 400 mm jeden element ma nieprzewidziane duże wykrzywienie i pęknięcie. Przykręcenie go siłą do łaty może zwiększyć naprężenie i nie rozwiązać problemu surowca; element powinien zostać oznaczony do oceny lub odrzutu."},{"heading":"Ćwiczenie bez ostrych narzędzi","text":"Przygotuj rysunki gontu łupanego i ciętego. Zapisz cechy powierzchni, potencjalne wady i wymagane pomiary. Ułóż kartę 10 elementów z wynikami pomiarów i decyzją jakościową. Praktyczną obsługę ostrzy i rozłupywania pozostaw instruktorowi."}],"illustration":"technique-gontarz","references":[{"label":"Źródło techniczne","url":"https://byggogbevar.no/pusse-opp/tak-og-tekking/artikler/tradisjonelle-tekkematerialer/"}],"learning":{"intro":"Gont łupany rozdziela drewno wzdłuż jego naturalnych płaszczyzn. Gont cięty powstaje przy użyciu piły, a niektóre regionalne odmiany wykonuje się także przy użyciu strugów. Każdy proces pozostawia inne ślady na powierzchni i może wymagać innych kryteriów kontroli. Celem nie jest nauczenie się niebezpiecznego łupania wyłącznie z tekstu.","situation":"W partii ciętych gontów o umownej długości 400 mm jeden element ma nieprzewidziane duże wykrzywienie i pęknięcie. Przykręcenie go siłą do łaty może zwiększyć naprężenie i nie rozwiązać problemu surowca; element powinien zostać oznaczony do oceny lub odrzutu.","task":"Przygotuj rysunki gontu łupanego i ciętego. Zapisz cechy powierzchni, potencjalne wady i wymagane pomiary. Ułóż kartę 10 elementów z wynikami pomiarów i decyzją jakościową. Praktyczną obsługę ostrzy i rozłupywania pozostaw instruktorowi.","question":"Jaki jest główny cel szablonu w przygotowaniu serii gontów?","options":["Służy do usuwania pyłu z pomieszczenia.","Automatycznie określa gatunek drzewa.","Pozwala kontrolować powtarzalność zaprojektowanych wymiarów i profilu.","Gwarantuje brak pęknięć w całej długości drewna."],"correct":2,"example":"Pozwala kontrolować powtarzalność zaprojektowanych wymiarów i profilu.","explanation":"Szablon wspiera kontrolę geometrii, lecz nie zastępuje oceny włókien i wad.","feedback":["Wróć do zależności opisanej w zadaniu. Szablon wspiera kontrolę geometrii, lecz nie zastępuje oceny włókien i wad.","Wróć do zależności opisanej w zadaniu. Szablon wspiera kontrolę geometrii, lecz nie zastępuje oceny włókien i wad.","Prawidłowo. Szablon wspiera kontrolę geometrii, lecz nie zastępuje oceny włókien i wad.","Wróć do zależności opisanej w zadaniu. Szablon wspiera kontrolę geometrii, lecz nie zastępuje oceny włókien i wad."]}}'::jsonb),
('gontarz',3,'4. Rysunek i nachylenie dachu: spadek, kąty i długość połaci','{"module":2,"curriculum_revision":4,"lesson_kind":"technical_curriculum","editorial_status":"review_needed","sections":[{"heading":"Dwie miary tego samego dachu","text":"Spadek podaje się jako relację podniesienia do poziomego przesunięcia, np. 4:12 oznacza 4 jednostki wysokości na 12 jednostek poziomu. Kąt dachu jest związany ze spadkiem tangensem. Spadek 4:12 odpowiada kątowi arctan(4/12) ≈ 18,4°. Nie znaczy to, że każdy typ gontu wolno montować na takim dachu."},{"heading":"Trójkąt prostokątny w pomiarze","text":"Jeśli pozioma odległość od okapu do kalenicy wynosi 3,0 m, a wznios 1,0 m, długość skośna wynosi √(3²+1²)=√10≈3,162 m. To długość geometryczna bez naddatków przy okapie i kalenicy. Powierzchnia połaci na planie nie jest powierzchnią połaci na nachyleniu."},{"heading":"Sprawdź dokumentację producenta i kraju","text":"Amerykańskie wytyczne dotyczące certyfikowanych cedar shingles podają swoje wymagania dla spadku i ekspozycji; nie są automatycznie polską lub norweską normą. Lokalny projekt musi uwzględniać wiatr, śnieg, ochronę przeciwpożarową, podłoże i właściwy wyrób."},{"heading":"Przykład błędu materiałowego","text":"Wykonawca liczy połacie 3 m na 4 m jak idealny prostokąt na rysunku poziomym: 12 m². Jeżeli rzeczywista skośna długość to 3,162 m, powierzchnia jednej połaci wynosi 3,162×4≈12,65 m² przed naddatkami i stratami. Pominięto ponad pół metra kwadratowego."},{"heading":"Ćwiczenie obliczeniowe","text":"Narysuj połaciowy trójkąt o run=3 m i rise=1 m. Policz kąt, długość po skosie oraz powierzchnię jednej połaci o długości okapu 4 m. Dopisz, czego nie uwzględnia taki model: kosze, lukarny, nawisy, detale i odpady."}],"illustration":"gontarz-spadek","references":[{"label":"Źródło techniczne","url":"https://www.cedarbureau.org/literature-education/installation-faq/"}],"learning":{"intro":"Spadek podaje się jako relację podniesienia do poziomego przesunięcia, np. 4:12 oznacza 4 jednostki wysokości na 12 jednostek poziomu. Kąt dachu jest związany ze spadkiem tangensem. Spadek 4:12 odpowiada kątowi arctan(4/12) ≈ 18,4°. Nie znaczy to, że każdy typ gontu wolno montować na takim dachu.","situation":"Wykonawca liczy połacie 3 m na 4 m jak idealny prostokąt na rysunku poziomym: 12 m². Jeżeli rzeczywista skośna długość to 3,162 m, powierzchnia jednej połaci wynosi 3,162×4≈12,65 m² przed naddatkami i stratami. Pominięto ponad pół metra kwadratowego.","task":"Narysuj połaciowy trójkąt o run=3 m i rise=1 m. Policz kąt, długość po skosie oraz powierzchnię jednej połaci o długości okapu 4 m. Dopisz, czego nie uwzględnia taki model: kosze, lukarny, nawisy, detale i odpady.","question":"Dach ma odległość poziomą 3 m i wznios 1 m. Jaką długość połaci od okapu do kalenicy daje model prostokątny?","options":["3,000 m, zawsze bez względu na wznios.","4,000 m, bo należy dodać obie długości.","9,000 m, bo 3×3=9.","Około 3,162 m, bo √(3²+1²)=√10."],"correct":3,"example":"Około 3,162 m, bo √(3²+1²)=√10.","explanation":"Twierdzenie Pitagorasa pozwala policzyć skośną długość; naddatki budowlane wymagają osobnych wymiarów.","feedback":["Wróć do zależności opisanej w zadaniu. Twierdzenie Pitagorasa pozwala policzyć skośną długość; naddatki budowlane wymagają osobnych wymiarów.","Wróć do zależności opisanej w zadaniu. Twierdzenie Pitagorasa pozwala policzyć skośną długość; naddatki budowlane wymagają osobnych wymiarów.","Wróć do zależności opisanej w zadaniu. Twierdzenie Pitagorasa pozwala policzyć skośną długość; naddatki budowlane wymagają osobnych wymiarów.","Prawidłowo. Twierdzenie Pitagorasa pozwala policzyć skośną długość; naddatki budowlane wymagają osobnych wymiarów."]}}'::jsonb),
('gontarz',4,'5. Zakład i ekspozycja: dlaczego trzy warstwy zatrzymują wodę','{"module":2,"curriculum_revision":4,"lesson_kind":"technical_curriculum","editorial_status":"review_needed","sections":[{"heading":"Ekspozycja i zakład to nie to samo","text":"Ekspozycja E to odcinek gontu widoczny po ułożeniu kolejnego rzędu. Długość L gontu dzieli się na część widoczną oraz część zakrytą. W wielowarstwowym pokryciu stosunek L/E może pomagać oszacować liczbę zachodzących warstw w dowolnym przekroju, ale prawidłowe rozwiązanie zależy od szczegółów montażu i wyrobu."},{"heading":"Przykład liczenia","text":"W ćwiczeniu L=400 mm, E=120 mm. Iloraz L/E=3,33; element rozciąga się więc na nieco ponad trzy wysokości ekspozycji. To ilustracja idei potrójnego pokrycia, nie zatwierdzony detal montażowy. Nie wolno z samego ilorazu przesądzić o wodoodporności, bo liczą się także styki boczne, układ rzędów i podłoże."},{"heading":"Dlaczego nie można zwiększać ekspozycji bez końca","text":"Gdy E rośnie, mniej długości gontu pozostaje pod kolejnymi rzędami. Przy określonym spadku i jakości materiału może to prowadzić do zbyt małego zakrycia ścieżek spływu wody. Certyfikowane wytyczne określają dopuszczalną ekspozycję jako funkcję długości, klasy i kąta dachu."},{"heading":"Przypadek dwóch ofert","text":"Firma A proponuje gont L=400 mm i ekspozycję 120 mm; firma B proponuje E=200 mm, żeby zużyć mniej elementów. W drugim przypadku L/E=2. Nie można wybrać tańszej oferty bez sprawdzenia, czy utrzymano wymagany układ i zalecenia dla dokładnego wyrobu."},{"heading":"Ćwiczenie diagnostyczne","text":"Na przekroju narysuj 4 kolejne rzędy o umownej długości L=400 mm i E=120 mm. Zaznacz nakładanie się gontów i kierunek spływu. Oblicz L/E dla 100, 120 i 200 mm, a potem wyjaśnij, dlaczego wynik nie zastępuje projektu detalu."}],"illustration":"gontarz-warstwy","references":[{"label":"Źródło techniczne","url":"https://www.cedarbureau.org/installation/roof-installation-manual/"}],"learning":{"intro":"Ekspozycja E to odcinek gontu widoczny po ułożeniu kolejnego rzędu. Długość L gontu dzieli się na część widoczną oraz część zakrytą. W wielowarstwowym pokryciu stosunek L/E może pomagać oszacować liczbę zachodzących warstw w dowolnym przekroju, ale prawidłowe rozwiązanie zależy od szczegółów montażu i wyrobu.","situation":"Firma A proponuje gont L=400 mm i ekspozycję 120 mm; firma B proponuje E=200 mm, żeby zużyć mniej elementów. W drugim przypadku L/E=2. Nie można wybrać tańszej oferty bez sprawdzenia, czy utrzymano wymagany układ i zalecenia dla dokładnego wyrobu.","task":"Na przekroju narysuj 4 kolejne rzędy o umownej długości L=400 mm i E=120 mm. Zaznacz nakładanie się gontów i kierunek spływu. Oblicz L/E dla 100, 120 i 200 mm, a potem wyjaśnij, dlaczego wynik nie zastępuje projektu detalu.","question":"Gont ma 400 mm długości, a jego ekspozycja wynosi 120 mm. Jak interpretujesz stosunek L/E≈3,33?","options":["Jest to długość w mm gotowa do cięcia.","To orientacyjna liczba wysokości ekspozycji pokrywanych długością gontu, nie kompletna norma montażu.","To dowód, że można dowolnie przesuwać styki boczne.","To liczba gwoździ wymagana do każdego gontu."],"correct":1,"example":"To orientacyjna liczba wysokości ekspozycji pokrywanych długością gontu, nie kompletna norma montażu.","explanation":"Iloraz mówi o zakładaniu pionowym, ale nie rozstrzyga doboru produktu ani konstrukcji i warunków lokalnych.","feedback":["Wróć do zależności opisanej w zadaniu. Iloraz mówi o zakładaniu pionowym, ale nie rozstrzyga doboru produktu ani konstrukcji i warunków lokalnych.","Prawidłowo. Iloraz mówi o zakładaniu pionowym, ale nie rozstrzyga doboru produktu ani konstrukcji i warunków lokalnych.","Wróć do zależności opisanej w zadaniu. Iloraz mówi o zakładaniu pionowym, ale nie rozstrzyga doboru produktu ani konstrukcji i warunków lokalnych.","Wróć do zależności opisanej w zadaniu. Iloraz mówi o zakładaniu pionowym, ale nie rozstrzyga doboru produktu ani konstrukcji i warunków lokalnych."]}}'::jsonb),
('gontarz',5,'6. Styki boczne i mocowanie: odchyłki, przesunięcie, gwoździe','{"module":2,"curriculum_revision":4,"lesson_kind":"technical_curriculum","editorial_status":"review_needed","sections":[{"heading":"Nie układaj wszystkich styków w jednej linii","text":"W pokryciach układanych na przemian łączenia boczne są przesunięte między rzędami. Gdyby styki leżały jeden nad drugim, woda mogłaby łatwiej przenikać przez pokrycie. Pożądany minimalny offset wynika z systemu i klasy produktu. Nie stosuj na ślepo szczegółów amerykańskich dla lokalnego takspon."},{"heading":"Mocowanie musi współpracować z drewnem","text":"Łączniki mocują gont do właściwego podłoża, ale nie powinny uniemożliwiać naturalnej pracy drewna ani go rozszczepiać. Ich liczba, położenie i materiał zależą od systemu, obciążenia, podłoża i lokalizacji. W wytycznych dla niektórych cedrowych pokryć stosuje się dwie sztuki na gont, ale to nie uniwersalna reguła dla każdej historycznej techniki."},{"heading":"Korozyjność środowiska","text":"Przy wybrzeżu i agresywnym środowisku znaczenie mają odpowiednie gatunki stali i odporność łączników. Sam wygląd gwoździa po montażu nie potwierdza klasy odporności korozyjnej. Wykonawca musi dobierać rodzaj według projektu i instrukcji właściwego wyrobu."},{"heading":"Przykład błędu","text":"Na zdjęciu dach ma pionowy pas styków z trzech kolejnych rzędów. Bez oględzin nie da się stwierdzić aktualnego przecieku, ale warto wskazać potencjalną drogę wody, porównać ją z wymaganiami wybranego systemu i zgłosić do fachowej oceny."},{"heading":"Ćwiczenie z widokiem","text":"Na papierze narysuj trzy rzędy po pięć gontów. Wariant A: styki jeden nad drugim; wariant B: kontrolowany mijankowy układ. Zaznacz różnicę potencjalnej drogi wody i wypisz, jakie dane są niezbędne do doboru łączników w realnym projekcie."}],"illustration":"gontarz-szczeliny","references":[{"label":"Źródło techniczne","url":"https://ibhs.org/guidance/ricowi-roof-guide-cedar-shingles-and-shakes/"}],"learning":{"intro":"W pokryciach układanych na przemian łączenia boczne są przesunięte między rzędami. Gdyby styki leżały jeden nad drugim, woda mogłaby łatwiej przenikać przez pokrycie. Pożądany minimalny offset wynika z systemu i klasy produktu. Nie stosuj na ślepo szczegółów amerykańskich dla lokalnego takspon.","situation":"Na zdjęciu dach ma pionowy pas styków z trzech kolejnych rzędów. Bez oględzin nie da się stwierdzić aktualnego przecieku, ale warto wskazać potencjalną drogę wody, porównać ją z wymaganiami wybranego systemu i zgłosić do fachowej oceny.","task":"Na papierze narysuj trzy rzędy po pięć gontów. Wariant A: styki jeden nad drugim; wariant B: kontrolowany mijankowy układ. Zaznacz różnicę potencjalnej drogi wody i wypisz, jakie dane są niezbędne do doboru łączników w realnym projekcie.","question":"Dlaczego styki boczne w kolejnych rzędach zwykle przesuwa się względem siebie?","options":["Aby ograniczyć powstanie ciągłej potencjalnej drogi przenikania wody.","Aby wszystkie gwoździe były widoczne po montażu.","Aby pominąć projekt mocowań i podłoża.","Aby zrezygnować z kontroli zakładu pionowego."],"correct":0,"example":"Aby ograniczyć powstanie ciągłej potencjalnej drogi przenikania wody.","explanation":"Przesunięcie styków współdziała z zakładami, aby nie tworzyć nieprzerwanej ścieżki dla wody.","feedback":["Prawidłowo. Przesunięcie styków współdziała z zakładami, aby nie tworzyć nieprzerwanej ścieżki dla wody.","Wróć do zależności opisanej w zadaniu. Przesunięcie styków współdziała z zakładami, aby nie tworzyć nieprzerwanej ścieżki dla wody.","Wróć do zależności opisanej w zadaniu. Przesunięcie styków współdziała z zakładami, aby nie tworzyć nieprzerwanej ścieżki dla wody.","Wróć do zależności opisanej w zadaniu. Przesunięcie styków współdziała z zakładami, aby nie tworzyć nieprzerwanej ścieżki dla wody."]}}'::jsonb),
('gontarz',6,'7. Okap, kalenica, kosz i obróbki: mapa spływu wody','{"module":3,"curriculum_revision":4,"lesson_kind":"technical_curriculum","editorial_status":"review_needed","sections":[{"heading":"Najpierw rozpoznaj geometrię dachu","text":"Okap jest dolną krawędzią połaci, kalenica — najwyższą linią przecięcia połaci, a kosz to wewnętrzne przecięcie połaci, w którym gromadzi się większy strumień wody. Komin, ściana i okno dachowe tworzą dodatkowe strefy przejściowe. W żadnym z tych miejsc nie wystarczy po prostu dociąć gontu do przeszkody."},{"heading":"Dlaczego okap wymaga uwagi","text":"Woda spływająca po pokryciu ma trafić poza konstrukcję lub do właściwej rynny. Detal okapu obejmuje także odpowiednie podparcie i ochronę krawędzi oraz rozwiązania na wiatr, śnieg i wilgoć. Wymagania pierwszych rzędów zależą od systemu — nie każdy historyczny układ stosuje to samo podwójne ułożenie."},{"heading":"Kosz i komin","text":"W koszu zbiera się woda z dwóch połaci, dlatego detal odwodnienia i uszczelnienia musi odpowiadać zwiększonemu obciążeniu. W obrębie komina czy ściany stosuje się zaprojektowane obróbki i połączenia, aby woda nie wpływała pod pokrycie. Sam silikon albo przypadkowa taśma nie zastępują poprawnego detalu."},{"heading":"Przykład oględzin","text":"Po deszczu zacieki pojawiają się na poddaszu blisko komina. Nie wystarczy policzyć uszkodzonych gontów: trzeba sprawdzić położenie zacieku względem obróbki, kierunku spływu, warstw podłoża i możliwej kondensacji. Woda wewnątrz może pojawić się niżej niż faktyczne miejsce nieszczelności."},{"heading":"Ćwiczenie projektu","text":"Na rysunku dwuspadowego dachu z kominem i dobudowaną połacią zaznacz pięć stref wysokiego ryzyka. Strzałkami pokaż strumienie wody ku okapowi, wskaż kosz i kalenicę, a przy każdym detalu wpisz dokument, który musi określić rozwiązanie."}],"illustration":"gontarz-warstwy","references":[{"label":"Źródło techniczne","url":"https://www.cedarbureau.org/installation/roof-installation-manual/"}],"learning":{"intro":"Okap jest dolną krawędzią połaci, kalenica — najwyższą linią przecięcia połaci, a kosz to wewnętrzne przecięcie połaci, w którym gromadzi się większy strumień wody. Komin, ściana i okno dachowe tworzą dodatkowe strefy przejściowe. W żadnym z tych miejsc nie wystarczy po prostu dociąć gontu do przeszkody.","situation":"Po deszczu zacieki pojawiają się na poddaszu blisko komina. Nie wystarczy policzyć uszkodzonych gontów: trzeba sprawdzić położenie zacieku względem obróbki, kierunku spływu, warstw podłoża i możliwej kondensacji. Woda wewnątrz może pojawić się niżej niż faktyczne miejsce nieszczelności.","task":"Na rysunku dwuspadowego dachu z kominem i dobudowaną połacią zaznacz pięć stref wysokiego ryzyka. Strzałkami pokaż strumienie wody ku okapowi, wskaż kosz i kalenicę, a przy każdym detalu wpisz dokument, który musi określić rozwiązanie.","question":"Który fragment dachu wymaga szczególnej kontroli z powodu spływu wody z dwóch sąsiednich połaci?","options":["Równy fragment połaci z dala od przejść.","Dekoracyjna deska w suchym pomieszczeniu.","Kosz dachowy, czyli wewnętrzna linia przecięcia połaci.","Wyłącznie numer ostatniego rzędu gontów."],"correct":2,"example":"Kosz dachowy, czyli wewnętrzna linia przecięcia połaci.","explanation":"Kosz skupia wodę z obu połaci i wymaga detalu zgodnego z projektem i systemem.","feedback":["Sprawdź kontekst, liczby i kryteria zadania. Kosz skupia wodę z obu połaci i wymaga detalu zgodnego z projektem i systemem.","Sprawdź kontekst, liczby i kryteria zadania. Kosz skupia wodę z obu połaci i wymaga detalu zgodnego z projektem i systemem.","Prawidłowo. Kosz skupia wodę z obu połaci i wymaga detalu zgodnego z projektem i systemem.","Sprawdź kontekst, liczby i kryteria zadania. Kosz skupia wodę z obu połaci i wymaga detalu zgodnego z projektem i systemem."]}}'::jsonb),
('gontarz',7,'8. Wentylacja i wilgoć: dach jako cały układ','{"module":3,"curriculum_revision":4,"lesson_kind":"technical_curriculum","editorial_status":"review_needed","sections":[{"heading":"Drewno musi mieć możliwość wysychania","text":"Żywotność dachu zależy nie tylko od jakości gontu, lecz także od warunków po obu stronach pokrycia. Wilgoć opadowa i wilgoć wewnętrzna mogą gromadzić się w przegrodzie, jeśli warstwy albo wentylacja nie odpowiadają przyjętemu rozwiązaniu. Długotrwale wilgotne drewno jest bardziej podatne na rozwój grzybów i deformacje."},{"heading":"Trzy odrębne funkcje","text":"Pokrycie odprowadza większość deszczu. Warstwa podkładowa/undertak ma swoją funkcję ochronną, zależną od systemu. Wentylacja i zdolność wysychania pomagają ograniczać utrzymywanie się wilgoci. Nie każda szczelna folia może być włożona w dowolne miejsce bez wpływu na parę wodną i warunki wilgotnościowe."},{"heading":"Co zmienia podłoże","text":"Gont montowany na ażurowych łatach pracuje w innych warunkach niż pokrycie na pełnym poszyciu. Instrukcja producenta może dopuszczać różne rozwiązania, ale wymaga sprawdzenia, czy wentylacja, mocowania i podkład współpracują. Nie wolno zakładać, że piana izolacyjna przyklejona do spodniej strony zawsze poprawia trwałość drewna."},{"heading":"Przykład możliwej kondensacji","text":"Pod pokryciem po zimnej nocy pojawiają się krople, choć nie padał deszcz. Źródłem może być kondensacja, więc naprawa przez dokładanie zewnętrznego uszczelniacza może pogorszyć warunki suszenia. Fachowa diagnostyka rozdziela infiltrację opadu od przepływu ciepłego wilgotnego powietrza."},{"heading":"Ćwiczenie na przekroju","text":"Narysuj trzy warianty podłoża: łaty ażurowe, pełne poszycie z przewidzianą wentylacją i pełne poszycie bez rozpoznanego rozwiązania wentylacyjnego. Wypisz pytania projektowe o wilgoć, temperaturę, przepływ powietrza i dopuszczone materiały."}],"illustration":"material-gontarz","references":[{"label":"Źródło techniczne","url":"https://www.cedarbureau.org/literature-education/installation-faq/"}],"learning":{"intro":"Żywotność dachu zależy nie tylko od jakości gontu, lecz także od warunków po obu stronach pokrycia. Wilgoć opadowa i wilgoć wewnętrzna mogą gromadzić się w przegrodzie, jeśli warstwy albo wentylacja nie odpowiadają przyjętemu rozwiązaniu. Długotrwale wilgotne drewno jest bardziej podatne na rozwój grzybów i deformacje.","situation":"Pod pokryciem po zimnej nocy pojawiają się krople, choć nie padał deszcz. Źródłem może być kondensacja, więc naprawa przez dokładanie zewnętrznego uszczelniacza może pogorszyć warunki suszenia. Fachowa diagnostyka rozdziela infiltrację opadu od przepływu ciepłego wilgotnego powietrza.","task":"Narysuj trzy warianty podłoża: łaty ażurowe, pełne poszycie z przewidzianą wentylacją i pełne poszycie bez rozpoznanego rozwiązania wentylacyjnego. Wypisz pytania projektowe o wilgoć, temperaturę, przepływ powietrza i dopuszczone materiały.","question":"Dlaczego dołożenie całkowicie nieprzepuszczalnej warstwy pod drewniane pokrycie nie zawsze jest dobrym pomysłem?","options":["Ponieważ może ograniczyć wysychanie konstrukcji, jeżeli warstwy i wentylacja nie są zaprojektowane jako układ.","Ponieważ każde drewno jest całkowicie niewrażliwe na wodę.","Ponieważ każdy dach ma obowiązkowo wyłącznie ażurowe podłoże.","Ponieważ kondensacja może wystąpić wyłącznie podczas deszczu."],"correct":0,"example":"Ponieważ może ograniczyć wysychanie konstrukcji, jeżeli warstwy i wentylacja nie są zaprojektowane jako układ.","explanation":"Potrzebna jest analiza fizyki budowli i rzeczywistej konstrukcji, a nie dobór jednej folii do każdego dachu.","feedback":["Prawidłowo. Potrzebna jest analiza fizyki budowli i rzeczywistej konstrukcji, a nie dobór jednej folii do każdego dachu.","Sprawdź kontekst, liczby i kryteria zadania. Potrzebna jest analiza fizyki budowli i rzeczywistej konstrukcji, a nie dobór jednej folii do każdego dachu.","Sprawdź kontekst, liczby i kryteria zadania. Potrzebna jest analiza fizyki budowli i rzeczywistej konstrukcji, a nie dobór jednej folii do każdego dachu.","Sprawdź kontekst, liczby i kryteria zadania. Potrzebna jest analiza fizyki budowli i rzeczywistej konstrukcji, a nie dobór jednej folii do każdego dachu."]}}'::jsonb),
('gontarz',8,'9. Diagnostyka gontu: pęknięcia, wygięcie, zgnilizna i łączniki','{"module":3,"curriculum_revision":4,"lesson_kind":"technical_curriculum","editorial_status":"review_needed","sections":[{"heading":"Rozpoznaj cztery kategorie objawów","text":"Pęknięcie przez grubość, wygięcie (cupping), podwijanie się (curling), miękki rozkładający się materiał i korozja łączników to różne objawy. Nie należy ich nazywać jednym słowem ''zużycie'', bo mogą wynikać z odmiennych przyczyn: jakości surowca, wilgotności, wad montażu lub środowiska."},{"heading":"Oględziny nie zastępują analizy","text":"W ocenie dokumentuj strefę połaci, kierunek pęknięcia, liczbę elementów, stan zakładów i obróbek. Ocena z poziomu ziemi może wykryć część nieprawidłowości, ale nie dowodzi stanu wszystkich warstw. Nie wchodź na stary dach bez potwierdzenia bezpieczeństwa i odpowiednich zabezpieczeń."},{"heading":"Wygięcie i warunki wysychania","text":"Jeśli strona gontu jest dużo bardziej wilgotna niż druga albo materiał ma niekorzystny układ włókien, może dochodzić do deformacji. Zbyt mało wentylacji i niewłaściwy rodzaj podłoża mogą przyspieszyć problemy. Przy wygięciu nie wystarczy wymienić elementu, jeśli warunki są systemowo złe."},{"heading":"Przykład klasyfikacji","text":"Na 20 m² widocznych jest 15 gontów z podwiniętymi dolnymi końcami, 2 pęknięte przy gwoździu i strefa mchu przy obróbce komina. Nie sumuj tego jako jednej przyczyny. Sporządź mapę wystąpień i oddziel mechaniczne uszkodzenia od trwałej wilgoci."},{"heading":"Ćwiczenie kontrolne","text":"Zaprojektuj tabelę 20 zdjęć z pięcioma polami: lokalizacja, objaw, ryzyko, hipoteza i potrzebny dowód. Zaznacz, które ustalenia możliwe są ze zdjęcia, a które wymagają inspekcji konstrukcji przez specjalistę."}],"illustration":"diagnosis-gontarz","references":[{"label":"Źródło techniczne","url":"https://byggogbevar.no/pusse-opp/tak-og-tekking/artikler/vedlikehold-av-flistak/"}],"learning":{"intro":"Pęknięcie przez grubość, wygięcie (cupping), podwijanie się (curling), miękki rozkładający się materiał i korozja łączników to różne objawy. Nie należy ich nazywać jednym słowem ''zużycie'', bo mogą wynikać z odmiennych przyczyn: jakości surowca, wilgotności, wad montażu lub środowiska.","situation":"Na 20 m² widocznych jest 15 gontów z podwiniętymi dolnymi końcami, 2 pęknięte przy gwoździu i strefa mchu przy obróbce komina. Nie sumuj tego jako jednej przyczyny. Sporządź mapę wystąpień i oddziel mechaniczne uszkodzenia od trwałej wilgoci.","task":"Zaprojektuj tabelę 20 zdjęć z pięcioma polami: lokalizacja, objaw, ryzyko, hipoteza i potrzebny dowód. Zaznacz, które ustalenia możliwe są ze zdjęcia, a które wymagają inspekcji konstrukcji przez specjalistę.","question":"Na wielu gontach występuje wygięcie, a podłoże nie ma rozpoznanej wentylacji. Jaka analiza jest najlepsza?","options":["Zamienić wszystkie łączniki na dłuższe bez projektu.","Uznać winę producenta bez sprawdzenia drewna i wilgoci.","Zamalować zewnętrzną stronę i zamknąć diagnostykę.","Sprawdzić wilgoć, przebieg włókien, podłoże i możliwość wysychania całego układu."],"correct":3,"example":"Sprawdzić wilgoć, przebieg włókien, podłoże i możliwość wysychania całego układu.","explanation":"Wada może być systemowa, więc kontrola obejmuje materiał i warunki pracy przegrody.","feedback":["Sprawdź kontekst, liczby i kryteria zadania. Wada może być systemowa, więc kontrola obejmuje materiał i warunki pracy przegrody.","Sprawdź kontekst, liczby i kryteria zadania. Wada może być systemowa, więc kontrola obejmuje materiał i warunki pracy przegrody.","Sprawdź kontekst, liczby i kryteria zadania. Wada może być systemowa, więc kontrola obejmuje materiał i warunki pracy przegrody.","Prawidłowo. Wada może być systemowa, więc kontrola obejmuje materiał i warunki pracy przegrody."]}}'::jsonb),
('gontarz',9,'10. Zabytkowy dach drewniany: konserwacja i zgodność technologii','{"module":4,"curriculum_revision":4,"lesson_kind":"technical_curriculum","editorial_status":"review_needed","sections":[{"heading":"Konserwacja to nie automatyczna modernizacja","text":"W zabytkowym dachu drewniane elementy mogą przenosić informacje o okresie powstania, regionalnej technice i wcześniejszych naprawach. Nie wolno bez oceny zamienić gontu łupanego na cięty, zmienić zakładów lub pokryć historycznej powierzchni przypadkową powłoką, nawet jeśli wydaje się to tańsze."},{"heading":"Rozpoznaj technikę historyczną","text":"Norweski system flis lub spon bywał układany z bocznym zachodzeniem, a technika zależy od regionu. Dokumentacja konserwatorska powinna wykazać, jaki typ naprawdę jest na dachu, co jest oryginałem, które fragmenty później wymieniono i jakie materiały odpowiadają historycznym rozwiązaniom."},{"heading":"Woda, grzyby i kontrola otoczenia","text":"Prace pielęgnacyjne uwzględniają zalegające liście, roślinność, ryzyka retencji wilgoci oraz detale odprowadzenia wody. Nie stosuj myjek wysokociśnieniowych ani agresywnych środków na starym gontowaniu bez procedury zatwierdzonej przez odpowiedniego specjalistę. Można naruszyć powierzchnię i przyspieszyć uszkodzenia."},{"heading":"Przykład błędnej renowacji","text":"Właściciel zabytkowej stodoły zamawia gładko cięte, barwione elementy w miejsce oryginalnego łupanego pokrycia, bez oględzin. Wymiana może zmienić wygląd i sposób pracy warstw; potrzebna jest dokumentacja, projekt naprawy i wymagane uzgodnienia konserwatorskie."},{"heading":"Ćwiczenie porównawcze","text":"Dla dwóch fotografii typów pokrycia sporządź kartę: metoda wykonania, krawędzie, przebieg włókien, sposób zakładania, ślady napraw, miejsca wnikania wody i pytania do konserwatora. Zaproponuj zakres minimalnej, nieinwazyjnej dokumentacji."}],"illustration":"craft-gontarz","references":[{"label":"Źródło techniczne","url":"https://byggogbevar.no/pusse-opp/tak-og-tekking/artikler/vedlikehold-av-flistak/"}],"learning":{"intro":"W zabytkowym dachu drewniane elementy mogą przenosić informacje o okresie powstania, regionalnej technice i wcześniejszych naprawach. Nie wolno bez oceny zamienić gontu łupanego na cięty, zmienić zakładów lub pokryć historycznej powierzchni przypadkową powłoką, nawet jeśli wydaje się to tańsze.","situation":"Właściciel zabytkowej stodoły zamawia gładko cięte, barwione elementy w miejsce oryginalnego łupanego pokrycia, bez oględzin. Wymiana może zmienić wygląd i sposób pracy warstw; potrzebna jest dokumentacja, projekt naprawy i wymagane uzgodnienia konserwatorskie.","task":"Dla dwóch fotografii typów pokrycia sporządź kartę: metoda wykonania, krawędzie, przebieg włókien, sposób zakładania, ślady napraw, miejsca wnikania wody i pytania do konserwatora. Zaproponuj zakres minimalnej, nieinwazyjnej dokumentacji.","question":"Dlaczego w zabytkowym dachu nie należy bez analizy zastąpić łupanych gontów ciętymi?","options":["Ponieważ nowy gont zawsze musi mieć ten sam kolor co stary.","Ponieważ można utracić cechy historycznej technologii i zmienić sposób pracy pokrycia.","Ponieważ każdy stary dach jest automatycznie całkowicie szczelny.","Ponieważ dokumentacja nie ma znaczenia, gdy drewno wygląda podobnie."],"correct":1,"example":"Ponieważ można utracić cechy historycznej technologii i zmienić sposób pracy pokrycia.","explanation":"Wartość konserwatorska obejmuje materiał i technikę, a nie jedynie zbliżony wygląd.","feedback":["Sprawdź kontekst, liczby i kryteria zadania. Wartość konserwatorska obejmuje materiał i technikę, a nie jedynie zbliżony wygląd.","Prawidłowo. Wartość konserwatorska obejmuje materiał i technikę, a nie jedynie zbliżony wygląd.","Sprawdź kontekst, liczby i kryteria zadania. Wartość konserwatorska obejmuje materiał i technikę, a nie jedynie zbliżony wygląd.","Sprawdź kontekst, liczby i kryteria zadania. Wartość konserwatorska obejmuje materiał i technikę, a nie jedynie zbliżony wygląd."]}}'::jsonb),
('gontarz',10,'11. BHP na dachu: ocena ryzyka, rusztowanie i zabezpieczenia','{"module":4,"curriculum_revision":4,"lesson_kind":"technical_curriculum","editorial_status":"review_needed","sections":[{"heading":"Praca na wysokości wymaga planu","text":"Praca na dachu może skończyć się ciężkim wypadkiem nawet przy niewielkiej wysokości, jeśli podłoże jest śliskie, kruche albo znajdują się w nim otwory. Ocena uwzględnia kąt połaci, największą wysokość upadku, konstrukcję i jej nośność, pogodę, drogę wejścia, transport gontów i zagrożenie dla osób pod dachem."},{"heading":"Pierwszeństwo ochrony zbiorowej","text":"Norweski Arbeidstilsynet zaleca i wymaga odpowiednio dobranych zbiorowych zabezpieczeń przed upadkiem jako pierwszego rozwiązania. Ręczna uprząż nie zastępuje automatycznie rusztowania, poręczy czy właściwego rozwiązania dostępu. Szczegóły klasy zabezpieczeń i konieczność dodatkowych systemów zależą od kąta i ryzyka."},{"heading":"Dach nie jest platformą roboczą","text":"Starych łat, pojedynczych gontów ani niezweryfikowanych płyt nie traktuj jako pewnego miejsca oparcia. Zapewnij dostęp zaprojektowaną drogą i sprawdź dokumentację rusztowania, systemu zabezpieczeń i nośności. Operator powinien mieć właściwe szkolenie, a plan ratunkowy musi wyjaśniać, jak udzielić pomocy po potencjalnym upadku."},{"heading":"Przykład odmowy rozpoczęcia","text":"Ekipa przyjeżdża na zabytkowy dach, gdzie widoczne są miękkie elementy poszycia i nie ma potwierdzonego rusztowania. Zamiast rozpoczynać demontaż należy przerwać plan, zabezpieczyć strefę i zlecić ocenę oraz odpowiednie rozwiązania bezpieczeństwa."},{"heading":"Ćwiczenie SJA/BHP","text":"Na kartce sporządź analizę ryzyka (SJA) dla wymiany pokrycia na pochyłym dachu: 10 zagrożeń, ocena ryzyka, działania zabezpieczające, kompetencje wykonawcy, plan ratunkowy i osoba zatwierdzająca. To zadanie dokumentacyjne — nie instrukcja samodzielnego wchodzenia na dach."}],"illustration":"mastery-gontarz","references":[{"label":"Źródło techniczne","url":"https://www.arbeidstilsynet.no/risikofylt-arbeid/arbeid-i-hoyden/unnga-fall-ved-arbeid-pa-tak/"}],"learning":{"intro":"Praca na dachu może skończyć się ciężkim wypadkiem nawet przy niewielkiej wysokości, jeśli podłoże jest śliskie, kruche albo znajdują się w nim otwory. Ocena uwzględnia kąt połaci, największą wysokość upadku, konstrukcję i jej nośność, pogodę, drogę wejścia, transport gontów i zagrożenie dla osób pod dachem.","situation":"Ekipa przyjeżdża na zabytkowy dach, gdzie widoczne są miękkie elementy poszycia i nie ma potwierdzonego rusztowania. Zamiast rozpoczynać demontaż należy przerwać plan, zabezpieczyć strefę i zlecić ocenę oraz odpowiednie rozwiązania bezpieczeństwa.","task":"Na kartce sporządź analizę ryzyka (SJA) dla wymiany pokrycia na pochyłym dachu: 10 zagrożeń, ocena ryzyka, działania zabezpieczające, kompetencje wykonawcy, plan ratunkowy i osoba zatwierdzająca. To zadanie dokumentacyjne — nie instrukcja samodzielnego wchodzenia na dach.","question":"Co należy zrobić, gdy nośność starego podłoża i zabezpieczenie krawędzi nie są potwierdzone?","options":["Wejść ostrożnie bez sprzętu, bo dach jest niski.","Pracować szybciej, aby skrócić narażenie.","Wstrzymać pracę, ocenić konstrukcję i zapewnić właściwe zabezpieczenia zbiorowe oraz dostęp.","Traktować same pojedyncze gonty jako bezpieczne stopnie."],"correct":2,"example":"Wstrzymać pracę, ocenić konstrukcję i zapewnić właściwe zabezpieczenia zbiorowe oraz dostęp.","explanation":"Ocenę ryzyka i rozwiązania zbiorowe trzeba ustalić przed pracą, a nie w trakcie.","feedback":["Sprawdź kontekst, liczby i kryteria zadania. Ocenę ryzyka i rozwiązania zbiorowe trzeba ustalić przed pracą, a nie w trakcie.","Sprawdź kontekst, liczby i kryteria zadania. Ocenę ryzyka i rozwiązania zbiorowe trzeba ustalić przed pracą, a nie w trakcie.","Prawidłowo. Ocenę ryzyka i rozwiązania zbiorowe trzeba ustalić przed pracą, a nie w trakcie.","Sprawdź kontekst, liczby i kryteria zadania. Ocenę ryzyka i rozwiązania zbiorowe trzeba ustalić przed pracą, a nie w trakcie."]}}'::jsonb),
('gontarz',11,'12. Projekt końcowy: kosztorys, ilości i kontrola jakości','{"module":4,"curriculum_revision":4,"lesson_kind":"technical_curriculum","editorial_status":"review_needed","sections":[{"heading":"Założenia projektu ćwiczeniowego","text":"Przyjmij jedną połaci dachu o wymiarach rzeczywistych 3 m po skosie i 4 m długości okapu, bez kominów i otworów. Powierzchnia wynosi 12 m². Przyjmij edukacyjny typ gontu o efektywnej szerokości 100 mm i ekspozycji 120 mm, bez nakładania tej wartości na realny dach bez aprobaty systemu."},{"heading":"Policz orientacyjny materiał","text":"Efektywne pokrycie jednej sztuki w tej uproszczonej siatce to 0,10 m×0,12 m=0,012 m². 12/0,012=1000 gontów. Jeżeli założysz 10% odrzutu całkowitej przygotowanej partii, trzeba oszacować 1000/(1−0,10)=1111,12, czyli co najmniej 1112 kandydatów. To uproszczenie ignoruje docinki przy okapie, kalenicy i detale."},{"heading":"Dodatkowe dane do prawdziwej wyceny","text":"Wycena wymaga rodzaju i jakości surowca, rzeczywistych wymiarów i efektywnej szerokości, układu startowego, zakładów, przerw, obróbek, nośności, wentylacji, łączników, transportu, usuwania odpadów oraz dostępu i zabezpieczeń. Nie wolno traktować 1112 jako zamówienia produkcyjnego na dach o nieznanym systemie."},{"heading":"Przykład rozbieżności","text":"Wykonawca liczy wyłącznie geometryczne 1000 sztuk i pomija odrzuty, okap oraz kalenicę. Podczas pracy okazuje się, że materiału brakuje, a wykonawca proponuje zwiększyć ekspozycję bez weryfikacji systemu. To niewłaściwe rozwiązanie: należy poprawić obmiar i uzupełnić materiał zgodny z projektem."},{"heading":"Praca końcowa","text":"Oddaj przekrój 3 kolejnych rzędów, schemat odprowadzenia wody, obliczenia 12 m² i 1112 sztuk, listę 12 wymagań odbiorczych, tabelę trzech potencjalnych usterek i ryzyk oraz projekt planu SJA. Wyjaśnij, które dane są przykładowe, a które musi dostarczyć uprawniony projektant i producent."}],"illustration":"gontarz-spadek","references":[{"label":"Źródło techniczne","url":"https://www.cedarbureau.org/installation/roof-installation-manual/"}],"learning":{"intro":"Przyjmij jedną połaci dachu o wymiarach rzeczywistych 3 m po skosie i 4 m długości okapu, bez kominów i otworów. Powierzchnia wynosi 12 m². Przyjmij edukacyjny typ gontu o efektywnej szerokości 100 mm i ekspozycji 120 mm, bez nakładania tej wartości na realny dach bez aprobaty systemu.","situation":"Wykonawca liczy wyłącznie geometryczne 1000 sztuk i pomija odrzuty, okap oraz kalenicę. Podczas pracy okazuje się, że materiału brakuje, a wykonawca proponuje zwiększyć ekspozycję bez weryfikacji systemu. To niewłaściwe rozwiązanie: należy poprawić obmiar i uzupełnić materiał zgodny z projektem.","task":"Oddaj przekrój 3 kolejnych rzędów, schemat odprowadzenia wody, obliczenia 12 m² i 1112 sztuk, listę 12 wymagań odbiorczych, tabelę trzech potencjalnych usterek i ryzyk oraz projekt planu SJA. Wyjaśnij, które dane są przykładowe, a które musi dostarczyć uprawniony projektant i producent.","question":"Połać ma 12 m², modelowa efektywna powierzchnia gontu to 0,012 m², a odrzut wynosi 10% całej przygotowanej partii. Ile kandydatów daje ten model?","options":["1000 sztuk, ponieważ odrzut nie zmienia zamówienia.","1100 sztuk, dokładnie, bo 10% oblicza się zawsze od 1000.","1200 sztuk, niezależnie od formatu.","1112 sztuk po zaokrągleniu 1000/0,9 w górę."],"correct":3,"example":"1112 sztuk po zaokrągleniu 1000/0,9 w górę.","explanation":"Przy wydajności 90% 1000/0,9=1111,12, zaokrąglając do całych sztuk w górę otrzymujemy 1112; model pomija rzeczywiste detale.","feedback":["Sprawdź kontekst, liczby i kryteria zadania. Przy wydajności 90% 1000/0,9=1111,12, zaokrąglając do całych sztuk w górę otrzymujemy 1112; model pomija rzeczywiste detale.","Sprawdź kontekst, liczby i kryteria zadania. Przy wydajności 90% 1000/0,9=1111,12, zaokrąglając do całych sztuk w górę otrzymujemy 1112; model pomija rzeczywiste detale.","Sprawdź kontekst, liczby i kryteria zadania. Przy wydajności 90% 1000/0,9=1111,12, zaokrąglając do całych sztuk w górę otrzymujemy 1112; model pomija rzeczywiste detale.","Prawidłowo. Przy wydajności 90% 1000/0,9=1111,12, zaokrąglając do całych sztuk w górę otrzymujemy 1112; model pomija rzeczywiste detale."]}}'::jsonb)
on conflict(course_slug,lesson_no) do update set title_pl=excluded.title_pl,material=public.ta_lessons.material||excluded.material,updated_at=now();
update public.ta_courses set description_pl='12 lekcji o gontach drewnianych: typy pokryć, materiałoznawstwo, narzędzia, ocena włókien drewna, rysunek i spadek połaci, ekspozycja i zakłady, styki boczne, obróbki dachu, wentylacja, uszkodzenia, konserwacja tradycyjnego pokrycia, BHP pracy na wysokości i projekt ilościowo-kosztowy. Kurs edukacyjny, nie daje uprawnień dekarskich; prawdziwa praca wymaga projektu, właściwych zabezpieczeń i fachowego nadzoru.' where slug='gontarz';
update public.ta_course_previews set
curiosity='Dlaczego rozłupywany gont może mieć inną trwałość niż cięty i co naprawdę powstrzymuje przeciek?',
scenario='Projektujesz 12 m² pokrycia z gontu 400 mm i modelową ekspozycją 120 mm. Obliczasz ilość, wybierasz drewno, oceniasz zakłady oraz ryzyka dachu.',
outcome_1='Odróżnisz lokalne typy drewnianych pokryć, odczytasz podstawowy rysunek i wskażesz materiałowe przyczyny pęknięć.',
outcome_2='Obliczysz spadek, długość połaci, ekspozycję i orientacyjny zapas materiału bez mylenia przykładu z wymaganiem budowlanym.',
outcome_3='Opracujesz mapę wilgoci, kontrolę jakości, plan konserwatorski i analizę ryzyka prac na wysokości.',
source_url='https://byggogbevar.no/pusse-opp/tak-og-tekking/artikler/vedlikehold-av-flistak/',
module_titles='["1. Drewno, typy pokryć i rysunek (1–3)","2. Obliczenia i zakłady (4–6)","3. Detale dachowe, wilgoć i diagnostyka (7–9)","4. Konserwacja, bezpieczeństwo i projekt (10–12)"]'::jsonb,
review_status='review_needed',
editorial_note='12 lekcji roboczych z przykładami i autorskimi zadaniami. Techniczne wskazówki Cedar Shake & Shingle Bureau są użyte wyłącznie jako porównanie dla danego produktu i nie stanowią ogólnej normy polskiej lub norweskiej. Bez profesjonalnej recenzji cieśli/dekarza, zweryfikowanego testu E2E i wdrożenia Expo nie deklarować kompletnego kursu.'
where course_slug='gontarz';
COMMIT;
